std::vector<Polygon2d> faces;
auto fit = arr.faces_begin();
auto fend = arr.faces_end();

for (; fit != fend; ++fit) {
    if (fit->is_fictitious() || fit->is_unbounded()) {
        continue;
    }

    std::vector<Point2d> points;
    std::vector<Arrangement2::Vertex_handle> vertices;

    Arrangement2::Face_const_handle face = fit;
    Arrangement2::Ccb_halfedge_const_circulator circ = face->outer_ccb();
    Arrangement2::Ccb_halfedge_const_circulator start = circ;

    do {
        Point2d p(circ->source()->point());
        points.push_back(p);
        ++circ;
    } while (circ != start);

    if (!points.empty()) {
        Polygon2d poly;
        poly.set_points(points.begin(), points.end());
        if (!poly.is_empty()) {
            faces.push_back(poly);
        }
    }
}

return faces;
// END_CODE

